 (p/'pdf-review.json').write_text(json.dumps({'passed':True,'pages':findings,'all40MarkersExactlyOnce':True,'allSavedVisibleTextComplete':True,'latestDataPresent':True,'noBackgroundOrHiddenFields':True,'visualReviewRequired':True},ensure_ascii=False,indent=2))
